def C(name, county, hoods, intro, local, notes, faqs, nearby):
    slug = "roof-inspection-" + name.lower().replace(" ", "-").replace("'", "")
    return dict(name=name, slug=slug, county=county, hoods=hoods, intro=intro,
                local=local, notes=notes, faqs=faqs, nearby=nearby)


